package com.meterflow.payments;
import com.meterflow.invoicing.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/payments/mock") public class PaymentController {private final InvoiceRepository invoices;public PaymentController(InvoiceRepository r){invoices=r;}@PostMapping("/{invoiceId}/pay") public Map<String,Object> pay(@PathVariable UUID invoiceId){var i=invoices.findById(invoiceId).orElseThrow();if(!i.getStatus().equals("FINALISED"))throw new IllegalArgumentException("Only finalised invoices can be paid");return Map.of("invoiceId",invoiceId,"paymentStatus","SUCCEEDED","provider","MOCK","message","Mock payment accepted");}}
